#
# Tightened from 99 classes to 28 based on static analysis of references
# from non-abilityms_files targets (mission_list, wantagent_manager,
# modular_object, appkit_native, abilitykit_native, intent_client,
# dataobsms, aa tool, cc tool).

1.0 {
  global:
    extern "C++" {
      # Core SA entry
      *AbilityManagerService*;
      *AbilityConnectCallbackRecipient*;

      # Records / Info (data classes used externally)
      *AbilityRecord*;
      *AbilityRunningInfo*;
      *ExtensionRunningInfo*;
      *ApplicationAnrListener*;
      *MissionInfo*;
      *MissionSnapshot*;
      *Mission*;
      *LaunchParam*;
      *LifeCycleStateInfo*;
      *StartOptions*;
      *Token*;
      *KeepAliveInfo*;
      *KeepAliveAppType*;
      *WantSenderInfo*;
      *SenderInfo*;

      # Required by mission_list (services/abilitymgr/mission sub-module)
      *AmsConfigurationParameter*;
      *AbilityRequest*;
      *AbilityEventHandler*;
      *CallRecord*;
      *AppExitReasonDataManager*;
      *AbilityStartWithWaitObserverManager*;
      *AbilityFirstFrameStateObserverManager*;

      # Utils / Helpers
      *AppScheduler*;
      *JsonUtils*;
      *KeepAliveSetter*;
      *UserController*;
    };
  local:
    *;
};
